import{_ as o,o as a,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"《中国社会各阶级的分析》：辨明敌友的科学方法","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/mao-zedong/class-analysis-friend-enemy.md","filePath":"topics/mao-zedong/class-analysis-friend-enemy.md"}'),n={name:"topics/mao-zedong/class-analysis-friend-enemy.md"};function s(d,t,i,l,h,u){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="《中国社会各阶级的分析》-辨明敌友的科学方法" tabindex="-1">《中国社会各阶级的分析》：辨明敌友的科学方法 <a class="header-anchor" href="#《中国社会各阶级的分析》-辨明敌友的科学方法" aria-label="Permalink to &quot;《中国社会各阶级的分析》：辨明敌友的科学方法&quot;">​</a></h1><blockquote><p>来源：逐篇拆解视频转写（2026-08-16）+ 毛泽东选集第一卷开篇经典 主题：毛选方法论 / 阶级分析 / 调研决策 / 敌友辩证法 核实说明：核心论断（敌友区分、农民主力、工人领导、中产两面性）为《毛泽东选集》公认要旨；<strong>视频特有的细节表述（如&quot;三大优势&quot;措辞）按视频转写，原文确切措辞以《毛选》为准。</strong></p></blockquote><hr><h2 id="一、核心命题-谁是我们的敌人-谁是我们的朋友" tabindex="-1">一、核心命题：谁是我们的敌人？谁是我们的朋友？ <a class="header-anchor" href="#一、核心命题-谁是我们的敌人-谁是我们的朋友" aria-label="Permalink to &quot;一、核心命题：谁是我们的敌人？谁是我们的朋友？&quot;">​</a></h2><p>1925年，毛泽东写下开篇第一句——<strong>&quot;谁是我们的敌人？谁是我们的朋友？&quot;</strong> 这是革命的首要问题，也是<strong>一切事业谋划的首要问题</strong>。</p><p>背景：辛亥革命后北洋军阀割据，中共反帝反封建方向对，但缺兵力、缺地盘、不知道依靠谁——&quot;凭感觉判断革命力量&quot;的混乱期。</p><hr><h2 id="二、核心方法-实地调研-不凭感觉" tabindex="-1">二、核心方法：实地调研，不凭感觉 <a class="header-anchor" href="#二、核心方法-实地调研-不凭感觉" aria-label="Permalink to &quot;二、核心方法：实地调研，不凭感觉&quot;">​</a></h2><p>毛主席回韶山实地调研，<strong>以民众的经济来源和被剥削状况为依据</strong>，科学判断各群体在革命中的立场。</p><blockquote><p>方法论内核：<strong>用客观的经济地位（利益结构）判断立场，而不是凭主观印象或道德评判。</strong></p></blockquote><hr><h2 id="三、各阶级科学划分-决策表" tabindex="-1">三、各阶级科学划分（决策表） <a class="header-anchor" href="#三、各阶级科学划分-决策表" aria-label="Permalink to &quot;三、各阶级科学划分（决策表）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>群体</th><th>经济地位</th><th>革命态度</th><th>战略定位</th></tr></thead><tbody><tr><td><strong>地主、买办</strong></td><td>靠剥削+依附帝国主义</td><td>革命损害其利益</td><td><strong>敌人，坚决反对</strong></td></tr><tr><td><strong>中产阶级（民族资产阶级）</strong></td><td>受压渴望革命，又怕损害财产</td><td><strong>两面性</strong></td><td>可争取但不可依靠，<strong>时刻提防变卦</strong></td></tr><tr><td><strong>小资产阶级</strong>（自耕农/小店主等）</td><td>家底薄弱，随时被剥削干净</td><td>分成：观望/随大流/积极三类</td><td><strong>可靠同盟军</strong>，天然就近革命</td></tr><tr><td><strong>半自耕农、贫农</strong>（农村绝大多数）</td><td>受最深层剥削</td><td>强烈渴望改变</td><td><strong>最结实、最广大的根基</strong>，讲透道理即最牢靠</td></tr><tr><td><strong>工业无产阶级</strong></td><td>一无所有</td><td>革命最彻底</td><td><strong>领导力量</strong>（三大优势：集中大城市易组织、一无所有最彻底、工人运动经验丰富）</td></tr></tbody></table><hr><h2 id="四、这个分析解决了什么根本问题" tabindex="-1">四、这个分析解决了什么根本问题 <a class="header-anchor" href="#四、这个分析解决了什么根本问题" aria-label="Permalink to &quot;四、这个分析解决了什么根本问题&quot;">​</a></h2><p><strong>&quot;把朋友搞得多多的，把敌人搞得少少的。&quot;</strong></p><p>科学分类 → 彻底解决<strong>依靠谁 / 联合谁 / 提防谁</strong>：</p><ul><li><strong>依靠</strong>：无产阶级（领导）+ 农民（最广大根基）</li><li><strong>联合</strong>：小资产阶级（可靠同盟）+ 中产阶级（争取但不依靠）</li><li><strong>提防</strong>：中产阶级的动摇性</li><li><strong>反对</strong>：地主买办</li></ul><p>历史检验：正是依靠正确的阶级分析，凝聚了广大农民，最终赢得革命胜利。</p><hr><h2 id="五、跨主题关联" tabindex="-1">五、跨主题关联 <a class="header-anchor" href="#五、跨主题关联" aria-label="Permalink to &quot;五、跨主题关联&quot;">​</a></h2><h3 id="_1-实践论-矛盾论-mao-主题" tabindex="-1">1. 实践论/矛盾论（mao 主题） <a class="header-anchor" href="#_1-实践论-矛盾论-mao-主题" aria-label="Permalink to &quot;1. 实践论/矛盾论（mao 主题）&quot;">​</a></h3><p>本篇是**&quot;调查研究的实践观&quot;**的样板——先实地调研掌握矛盾（经济地位），再判断敌友（分清主次矛盾）。与 <code>mao-philosophy-practice-contradiction.md</code> 的&quot;没有调查没有发言权&quot;直接同构：<strong>决策前必先摸清利益结构。</strong></p><h3 id="_2-解闷-表面归因陷阱-今天游泳主题" tabindex="-1">2. 解闷/表面归因陷阱（今天游泳主题） <a class="header-anchor" href="#_2-解闷-表面归因陷阱-今天游泳主题" aria-label="Permalink to &quot;2. 解闷/表面归因陷阱（今天游泳主题）&quot;">​</a></h3><p>&quot;凭感觉判断革命力量&quot; = 凭表象判断，与游泳&quot;沉腿练核心&quot;同属&quot;<strong>在错误层面加力/未先排查根因</strong>&quot;。阶级分析要先查经济地位（根因），如同自由泳先查头/呼吸（根因）。</p><h3 id="_3-创业-职场-定位→站队→落点映射" tabindex="-1">3. 创业/职场：定位→站队→落点映射 <a class="header-anchor" href="#_3-创业-职场-定位→站队→落点映射" aria-label="Permalink to &quot;3. 创业/职场：定位→站队→落点映射&quot;">​</a></h3><p>&quot;对谁不抱幻想、对谁全力依靠、对谁时刻提防&quot;是<strong>任何组织博弈的理性决策模型</strong>——客户/合作伙伴/竞争者/摇摆者，可用同一张表列经济动机（各自利益结构）来定策略，而非感情用事。</p><h3 id="_4-天轴困局-重构而非外挂-延展" tabindex="-1">4. 天轴困局（重构而非外挂）延展 <a class="header-anchor" href="#_4-天轴困局-重构而非外挂-延展" aria-label="Permalink to &quot;4. 天轴困局（重构而非外挂）延展&quot;">​</a></h3><p>&quot;把朋友搞得多多的，把敌人搞得少少的&quot;本质是<strong>结构性取舍</strong>，与&quot;砍轴重构非外挂&quot;同源——真正有效的不是四处补救（外挂），而是先分清哪些是支点（朋友/可依靠）、哪些该果断放弃（敌人/阻力）。</p><hr><h2 id="六、当代指导意义-应用框架" tabindex="-1">六、当代指导意义（应用框架） <a class="header-anchor" href="#六、当代指导意义-应用框架" aria-label="Permalink to &quot;六、当代指导意义（应用框架）&quot;">​</a></h2><p>不是照搬&quot;阶级&quot;概念，而是迁移其<strong>方法论结构</strong>到个人/职场/团队：</p><blockquote><p><strong>调研利益结构 → 划分立场光谱 → 定&quot;依靠/联合/提防/反对&quot;策略 → 集中力量结盟关键支点</strong></p></blockquote><ul><li>职场：谁与我利益正相关（盟友）？谁与我有结构性冲突（对手）？谁是摇摆者（争取但防变卦）？</li><li>创业：谁是不可或缺的客户/伙伴（依靠）？哪些需求该果断不碰（敌人）？</li><li>决策前先问自己：<strong>我掌握了客观情况吗，还是凭感觉？</strong></li></ul><hr><h2 id="七、一句话带走" tabindex="-1">七、一句话带走 <a class="header-anchor" href="#七、一句话带走" aria-label="Permalink to &quot;七、一句话带走&quot;">​</a></h2><p><strong>先分辨敌友，再集中力量。</strong> 一切有效行动始于&quot;谁是同盟、谁是阻力&quot;的清醒判断——而这判断必须来自对利益结构的实地调研，而非主观感觉。</p><hr><h2 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h2><p>中国社会各阶级的分析、毛泽东、毛选、敌友、阶级分析、调研、依靠谁、联合谁、提防谁、把朋友搞得多多的、中产阶级两面性、无产阶级领导、农民主力</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><p>mao-zedong/mao-philosophy-practice-contradiction · mao-zedong/mao-collected-works · fitness/swimming（沉腿=表面归因同构）</p>',42)])])}const q=o(n,[["render",s]]);export{c as __pageData,q as default};
